<?php
require_once __DIR__.'/../includes/bootstrap.php';require_admin();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);try{
 if($action==='save'){$name=trim($_POST['name']??'');$cat=(int)($_POST['category_id']??0);$price=trim($_POST['price']??'');$price=$price===''?null:(float)$price;$stock=(int)($_POST['stock_quantity']??0);if($name===''||$cat<1||$stock<0||($price!==null&&$price<0))throw new RuntimeException('Enter a name, category, non-negative price and stock.');$img=upload_image('image','products');$data=[$cat,$name,trim($_POST['description']??'')?:null,trim($_POST['brand']??'')?:null,trim($_POST['specifications']??'')?:null,trim($_POST['unit']??'')?:null,$price,$stock,(int)isset($_POST['is_active'])];if($id){if($img){$st=$pdo->prepare("UPDATE products SET category_id=?,name=?,description=?,brand=?,specifications=?,unit=?,price=?,stock_quantity=?,is_active=?,image_path=? WHERE id=?");$st->execute([...$data,$img,$id]);}else{$st=$pdo->prepare("UPDATE products SET category_id=?,name=?,description=?,brand=?,specifications=?,unit=?,price=?,stock_quantity=?,is_active=? WHERE id=?");$st->execute([...$data,$id]);}}else{$st=$pdo->prepare("INSERT INTO products(category_id,name,description,brand,specifications,unit,price,stock_quantity,is_active,image_path) VALUES(?,?,?,?,?,?,?,?,?,?)");$st->execute([...$data,$img]);}flash('Product saved.');redirect('/lakshmi-electricals/admin/products.php');}
 if($action==='delete'){$st=$pdo->prepare("UPDATE products SET is_active=0 WHERE id=?");$st->execute([$id]);flash('Product hidden from the public catalogue.');redirect('/lakshmi-electricals/admin/products.php');}
 }catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Could not save product. Check the category and entered values.';}}
$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare("SELECT * FROM products WHERE id=?");$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}
$cats=$pdo->query("SELECT id,name FROM categories ORDER BY name")->fetchAll();$q=trim($_GET['q']??'');$sql="SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id";$args=[];if($q!==''){$sql.=" WHERE p.name LIKE ? OR c.name LIKE ? OR p.brand LIKE ?";$l='%'.$q.'%';$args=[$l,$l,$l];}$sql.=" ORDER BY p.updated_at DESC";$st=$pdo->prepare($sql);$st->execute($args);$products=$st->fetchAll();
$pageTitle='Manage products';require __DIR__.'/../includes/header.php';?>
<div class="admin-layout"><aside class="admin-sidebar"><span class="eyebrow">MANAGEMENT</span><h2>Admin panel</h2><a href="/lakshmi-electricals/admin/dashboard.php">Dashboard</a><a href="/lakshmi-electricals/admin/categories.php">Categories</a><a class="active" href="/lakshmi-electricals/admin/products.php">Products</a><a href="/lakshmi-electricals/admin/orders.php">Order requests</a><a href="/lakshmi-electricals/admin/users.php">Customers</a></aside><section class="admin-content"><div class="section-heading"><div><span class="eyebrow">INVENTORY</span><h1>Products</h1></div></div><?php if($error): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?><form class="form-card compact-form" method="post" enctype="multipart/form-data"><h2><?= $edit?'Edit product':'Add product' ?></h2><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><div class="form-grid"><label>Product name<input name="name" required maxlength="180" value="<?= e($edit['name']??'') ?>"></label><label>Category<select name="category_id" required><option value="">Choose category</option><?php foreach($cats as $c): ?><option value="<?= (int)$c['id'] ?>" <?= (int)($edit['category_id']??0)===(int)$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select></label><label>Price (INR; leave blank for enquiry)<input type="number" min="0" step="0.01" name="price" value="<?= e(isset($edit['price'])?(string)$edit['price']:'') ?>"></label><label>Unit (piece, metre, packet, etc.)<input name="unit" maxlength="40" value="<?= e($edit['unit']??'') ?>"></label><label>Brand<input name="brand" maxlength="100" value="<?= e($edit['brand']??'') ?>"></label><label>Stock quantity<input type="number" name="stock_quantity" min="0" required value="<?= e((string)($edit['stock_quantity']??0)) ?>"></label></div><label>Description<textarea name="description" rows="2"><?= e($edit['description']??'') ?></textarea></label><label>Specifications / size<textarea name="specifications" rows="2"><?= e($edit['specifications']??'') ?></textarea></label><label>Product image (JPG, PNG, WEBP; max 3 MB)<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><label class="check-label"><input type="checkbox" name="is_active" value="1" <?= !isset($edit['is_active'])||(int)$edit['is_active']===1?'checked':'' ?>> Visible in public catalogue</label><div class="form-actions"><button class="btn btn-gold">Save product</button><?php if($edit): ?><a class="btn btn-outline" href="/lakshmi-electricals/admin/products.php">Cancel</a><?php endif; ?></div></form><form class="search-bar admin-search" method="get"><input name="q" value="<?= e($q) ?>" placeholder="Search product, brand or category"><button class="btn btn-outline">Search</button></form><div class="panel"><div class="table-scroll"><table><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><strong><?= e($p['name']) ?></strong><br><small><?= e($p['brand']) ?></small></td><td><?= e($p['category_name']) ?></td><td><?= $p['price']!==null?money($p['price']):'On enquiry' ?></td><td><?= (int)$p['stock_quantity'] ?></td><td><?= $p['is_active']?'Visible':'Hidden' ?></td><td><a class="text-link" href="?edit=<?= (int)$p['id'] ?>">Edit</a> <form class="inline-delete" method="post" onsubmit="return confirm('Hide this product from the public catalogue?')"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><button class="link-button danger">Hide</button></form></td></tr><?php endforeach; ?></tbody></table></div></div></section></div>
